import {UnifiedJournal} from './journal-unified.js';
// Shared P2 client boundary. The V6 copy is generated by sync-lifecycle.mjs.
export const AccountBaselineSettings={initialCapital:0,defaultRisk1R:0,frictionCostR:0,dailyLossLimit:0,personalDailyLimit:0,maxDrawdown:0};
export const JournalLifecycle = {
  statuses:['UNINITIALIZED_FIRST_RUN','CLEAN_PRODUCTION','DEMO_SANDBOX','CLEAN_SLATE_LOCKED','LIVE_PRODUCTION'],
  origins:['MOCK_SEED_V3','USER_LIVE','IMPORTED_VERIFIED'],
  baseline:AccountBaselineSettings,
  demoBaseline:{initialCapital:10000,defaultRisk1R:100,frictionCostR:.05,dailyLossLimit:1000,personalDailyLimit:500,maxDrawdown:2000},
  key(owner='device'){return 'tuan-journal-lifecycle-v1'+(owner==='device'?'':':'+owner);},
  read(owner='device',storage=globalThis.localStorage){const raw=storage?.getItem(this.key(owner));if(!raw)return {status:'UNINITIALIZED_FIRST_RUN',noMock:false};const value=JSON.parse(raw);if(!this.statuses.includes(value.status)||typeof value.noMock!=='boolean')throw Error('Trạng thái dữ liệu không hợp lệ; hãy giữ bản sao trước khi sửa');return value;},
  set(status,owner='device',storage=globalThis.localStorage){if(!this.statuses.includes(status))throw Error('Trạng thái dữ liệu không hợp lệ');const before=this.read(owner,storage);if(status==='UNINITIALIZED_FIRST_RUN'&&before.status!=='UNINITIALIZED_FIRST_RUN')throw Error('Không thể quay lại lần khởi tạo đầu tiên');if(status==='DEMO_SANDBOX'&&before.noMock)throw Error('Đã khóa dữ liệu mẫu; dùng hồ sơ trình duyệt riêng để xem mẫu');const value={status,noMock:before.noMock||status==='CLEAN_SLATE_LOCKED'};if(JSON.stringify(before)!==JSON.stringify(value)){storage?.setItem(this.key(owner),JSON.stringify(value));this.signal(owner);}return value;},
  signal(owner='device'){if(typeof window==='undefined')return;window.dispatchEvent(new CustomEvent('journal-lifecycle-updated',{detail:{owner}}));try{const ch=new BroadcastChannel('tuan-classic-journal');ch.postMessage({sender:'lifecycle',owner});ch.close();}catch{}},
  origin(record){return this.origins.includes(record.origin)?record.origin:'USER_LIVE';},
  signature(value){const normalize=v=>Array.isArray(v)?v.map(normalize):v&&typeof v==='object'?Object.fromEntries(Object.keys(v).filter(k=>k!=='origin').sort().map(k=>[k,normalize(v[k])])):v;return JSON.stringify(normalize(value));},
  tag(records){return records.map(t=>({...t,origin:this.origin(t)}));},
  changes(before,after){const old=new Map(before.map(t=>[String(t.id),t])),result=[];for(const t of after){const b=old.get(String(t.id));old.delete(String(t.id));if(JSON.stringify(b)!==JSON.stringify(t))result.push({id:String(t.id),before:b||null,after:t});}for(const t of old.values())result.push({id:String(t.id),before:t,after:null});return result;},
  log(before,after,history=[],now=new Date().toISOString()){const changes=this.changes(before,after);return changes.length?[...history,{origin:'USER_LIVE',at:now,changes}].slice(-50):history;},
  undo(rows,history){if(!history.length)throw Error('Chưa có thao tác để hoàn tác');const op=history.at(-1),map=new Map(rows.map(t=>[String(t.id),t]));for(const c of op.changes)if(JSON.stringify(map.get(c.id)||null)!==JSON.stringify(c.after))throw Error('Dữ liệu đã thay đổi; không thể hoàn tác đè lên bản mới');for(const c of op.changes){if(c.before)map.set(c.id,c.before);else map.delete(c.id);}return {rows:[...map.values()],history:history.slice(0,-1)};},
  trash(rows,removed,trash=[],now=new Date().toISOString()){const ids=new Set(removed.map(String));return {rows:rows.filter(t=>!ids.has(String(t.id))),trash:[...trash,...rows.filter(t=>ids.has(String(t.id))).map(trade=>({origin:this.origin(trade),trade,deletedAt:now,expiresAt:new Date(Date.parse(now)+30*86400000).toISOString()}))]};},
  restore(rows,trash,id,now=Date.now()){const item=trash.find(t=>String(t.trade.id)===String(id));if(!item||Date.parse(item.expiresAt)<now)throw Error('Đã hết cửa sổ khôi phục 30 ngày');if(rows.some(t=>String(t.id)===String(id)))throw Error('ID đã tồn tại; không ghi đè');return {rows:[...rows,structuredClone(item.trade)],trash:trash.filter(t=>t!==item)};},
  async jsonValue(value){if(typeof Blob!=='undefined'&&value instanceof Blob){let binary='';for(const byte of new Uint8Array(await value.arrayBuffer()))binary+=String.fromCharCode(byte);return {kind:'tuannhatky-binary-v1',type:value.type,name:value.name??null,lastModified:value.lastModified??null,base64:btoa(binary)};}if(Array.isArray(value)){const out=[];for(const v of value)out.push(await this.jsonValue(v));return out;}if(value&&typeof value==='object'){const out={};for(const [k,v] of Object.entries(value))out[k]=await this.jsonValue(v);return out;}return value;},
  async saveBackup(payload,filename='tuannhatky-before-change.json'){
    const text=JSON.stringify(payload,null,2);
    if(typeof globalThis.showSaveFilePicker==='function'){
      const handle=await globalThis.showSaveFilePicker({suggestedName:filename,types:[{description:'JSON',accept:{'application/json':['.json']}}]}),stream=await handle.createWritable();try{await stream.write(text);await stream.close();}catch(error){await stream.abort().catch(()=>{});throw error;}if(await (await handle.getFile()).text()!==text)throw Error('Không xác minh được bản JSON đã lưu');return {saved:true,text};
    }
    const blob=new Blob([text],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),3000);
    // A click cannot establish download completion. Read back the file before allowing deletion.
    await new Promise((resolve,reject)=>{const dialog=document.createElement('dialog');dialog.setAttribute('aria-label','Xác minh bản sao JSON');dialog.innerHTML='<form method="dialog" style="max-width:32rem;padding:1.5rem"><h2>Xác minh bản sao đã tải</h2><p>Chọn lại file JSON vừa tải để kiểm tra trước khi xóa hoặc thay dữ liệu.</p><input class="p2-backup-file" aria-label="Chọn bản JSON vừa tải" type="file" accept=".json,application/json"><p role="status"></p><button value="cancel">Hủy thao tác</button></form>';document.body.appendChild(dialog);dialog.querySelector('input').onchange=async event=>{try{const file=event.target.files?.[0];if(!file||await file.text()!==text){dialog.querySelector('[role=status]').textContent='File không khớp; dữ liệu chưa bị thay đổi.';return;}dialog.close('saved');}catch(e){dialog.querySelector('[role=status]').textContent=String(e);}};dialog.onclose=()=>{const ok=dialog.returnValue==='saved';dialog.remove();ok?resolve(true):reject(Error('Đã hủy: dữ liệu được giữ nguyên'));};dialog.showModal();});return {saved:true,text};
  },
  async database(name){if(typeof indexedDB==='undefined')throw Error('Không truy cập được IndexedDB');if(indexedDB.databases&&!((await indexedDB.databases()).some(d=>d.name===name)))return null;return new Promise((resolve,reject)=>{const r=indexedDB.open(name);r.onupgradeneeded=()=>{r.transaction.abort();};r.onsuccess=()=>resolve(r.result);r.onerror=()=>r.error?.name==='AbortError'?resolve(null):reject(r.error);r.onblocked=()=>reject(Error('Hãy đóng tab đang giữ kho dữ liệu'));});},
  ownsClassicKey(key,owner){const suffix=owner==='device'?'':':'+owner,exact=['ledger-cache:tuan-trader-trades'+suffix,'risk:'+owner,'notes:'+owner,'mutation_oplog:'+owner,'tuan-trader-notes'+suffix];return exact.includes(key)||key.endsWith(':base:'+owner)||key.startsWith('recovery:tuan-trader-trades'+suffix+':')||['trash:','recovery:','import-progress:','evidence:','restored-risk:'].some(p=>key.startsWith(p+owner+':')||key===p+owner);},
  async localBackup(owner='device'){
    const localStorageData={};for(const key of Object.keys(localStorage))if(/^(tuan-|tuannhatky_|TNK_)/.test(key))localStorageData[key]=localStorage.getItem(key);
    const databases={};for(const name of ['tuan-classic-local-first-v1','tuannhatky_pro_unified_v1',UnifiedJournal.name]){const db=await this.database(name);if(!db)continue;try{const tables={};for(const table of Array.from(db.objectStoreNames))tables[table]=await new Promise((resolve,reject)=>{const tx=db.transaction(table),r=tx.objectStore(table).getAll();r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});databases[name]=tables;}finally{db.close();}}
    const unified=databases[UnifiedJournal.name];if(unified)for(const name of Object.keys(unified))unified[name]=unified[name].filter(row=>row.owner===owner||name==='meta'&&row.key===owner);
    const classic=databases['tuan-classic-local-first-v1'];if(classic){classic.values=(classic.values||[]).filter(r=>this.ownsClassicKey(r.key,owner));classic.queue=(classic.queue||[]).filter(r=>r.owner===owner);}
    const v6=databases['tuannhatky_pro_unified_v1'],active=v6?.risk_profiles?.[0]?.ledger_metadata?.extra?.classicSync?.owner||'device';if(v6){if(active!==owner)for(const table of ['risk_profiles','trades_journal','simulation_snapshots'])v6[table]=[];v6.restore_archives=(v6.restore_archives||[]).filter(r=>(r.state?.extra?.classicSync?.owner||'device')===owner);}
    const suffix=owner==='device'?'':':'+owner;for(const key of Object.keys(localStorageData)){if(key==='tuannhatky_pro_unified_v1'){let actual=active;try{const value=JSON.parse(localStorageData[key]);if(value.storage!=='indexeddb')actual=value.extra?.classicSync?.owner||'device';}catch{}if(actual!==owner)delete localStorageData[key];}else if(!['tuan-trader-trades'+suffix,'tuan-trader-notes'+suffix,'tuan-trader-demo-mode-v1'+suffix,this.key(owner)].includes(key)&&!(owner==='device'&&!key.includes(':')&&!key.startsWith('tuan-journal-lifecycle-v1:')))delete localStorageData[key];}
    return {format:'tuannhatky-browser-backup',version:1,owner,exportedAt:new Date().toISOString(),localStorage:localStorageData,databases:await this.jsonValue(databases)};
  },
  async unchangedBrowser(browser,owner){const current=await this.localBackup(owner),withoutTime=x=>JSON.stringify({...x,exportedAt:null});if(withoutTime(current)!==withoutTime(browser))throw Error('Dữ liệu trình duyệt đã thay đổi sau sao lưu; hãy lưu bản mới trước khi xóa');},
  async prepare(view,owner='device',cloud=false){const browser=await this.localBackup(owner);let remote=null;if(cloud){const r=await fetch('/api/journal-reset',{headers:{'X-Journal-Owner':owner},cache:'no-store'});if(!r.ok)throw Error('Không sao lưu được cloud; dữ liệu chưa bị thay đổi ('+r.status+')');remote=await r.json();if(remote.owner!==owner)throw Error('Tài khoản đã thay đổi');}const bundle={format:'tuannhatky-safety-backup',version:1,owner,views:view,browser,cloud:remote},receipt=await this.saveBackup(bundle);await this.unchangedBrowser(browser,owner);return {bundle,receipt};},
  async hardReset(prepared,owner='device',cloud=false){if(!prepared?.receipt?.saved||prepared.bundle.owner!==owner)throw Error('Chưa xác minh được bản sao đã lưu');if(prompt('Xóa sạch nhật ký, thùng rác, lịch sử hoàn tác và bộ nhớ đệm của tài khoản này. Giữ đăng nhập và kết nối broker. Nhập XOA NHAT KY để xác nhận:')!=='XOA NHAT KY')throw Error('Đã hủy: dữ liệu được giữ nguyên');await this.unchangedBrowser(prepared.bundle.browser,owner);let result=null;if(cloud){const r=await fetch('/api/journal-reset',{method:'POST',headers:{'Content-Type':'application/json','X-Journal-Owner':owner},body:JSON.stringify({owner,checksum:prepared.bundle.cloud?.checksum,downloadVerified:true,confirmation:'XOA NHAT KY'})});result=await r.json();if(!r.ok||!result.reset)throw Error(result.error||'Chưa reset được cloud; bản trên thiết bị được giữ');}await this.resetLocal(owner);return result;},
  async resetLocal(owner='device'){
    await UnifiedJournal.reset(owner);
    const db=await this.database('tuan-classic-local-first-v1');if(db)try{const names=['values','queue'].filter(n=>db.objectStoreNames.contains(n));if(names.length)await new Promise((resolve,reject)=>{const tx=db.transaction(names,'readwrite');if(names.includes('values')){const r=tx.objectStore('values').openCursor();r.onsuccess=()=>{const c=r.result;if(!c)return;const k=String(c.key);if(this.ownsClassicKey(k,owner))c.delete();c.continue();};}if(names.includes('queue')){const q=tx.objectStore('queue').openCursor();q.onsuccess=()=>{const c=q.result;if(c){if(c.value.owner===owner)c.delete();c.continue();}};}tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error);});}finally{db.close();}
    let ownsV6=false;const v6=await this.database('tuannhatky_pro_unified_v1');if(v6)try{const profiles=await new Promise((resolve,reject)=>{const r=v6.transaction('risk_profiles').objectStore('risk_profiles').getAll();r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});const actual=profiles[0]?.ledger_metadata?.extra?.classicSync?.owner||'device';ownsV6=actual===owner;if(ownsV6||v6.objectStoreNames.contains('restore_archives'))await new Promise((resolve,reject)=>{const names=ownsV6?Array.from(v6.objectStoreNames):['restore_archives'],tx=v6.transaction(names,'readwrite');for(const table of names){const store=tx.objectStore(table);if(table!=='restore_archives')store.clear();else{const r=store.openCursor();r.onsuccess=()=>{const c=r.result;if(c){if((c.value.state?.extra?.classicSync?.owner||'device')===owner)c.delete();c.continue();}};}}tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error);});}finally{v6.close();}
    const suffix=owner==='device'?'':':'+owner;for(const key of ['tuan-trader-trades','tuan-trader-notes','tuan-trader-demo-mode-v1'])localStorage.removeItem(key+suffix);if(owner==='device'){for(const key of ['tuannhatky_trial_v3_data','tuannhatky_trial_v3_extra','tuannhatky_trial_v3_ext2','tuannhatky_v10_db_state','tuan-trader-system-range-v1','tuan-trader-valuation-lab-v4','tuan-trader-dcf-model-v1','tuan-trader-dcf-model-v2','tuan-analysis-view-v1'])localStorage.removeItem(key);}const raw=localStorage.getItem('tuannhatky_pro_unified_v1');if(raw){const s=JSON.parse(raw);if((s.storage==='indexeddb'?ownsV6:(s.extra?.classicSync?.owner||'device')===owner))localStorage.removeItem('tuannhatky_pro_unified_v1');}if(typeof caches!=='undefined')for(const name of await caches.keys())if(name.startsWith('tuannhatky-v6-')||name.startsWith('workbox-')&&name.includes('/v6/'))await caches.delete(name);this.set('CLEAN_SLATE_LOCKED',owner);localStorage.setItem('tuan-trader-demo-mode-v1'+suffix,'false');this.signal(owner);
  }
};
